"""Data agent: PostgreSQL -> SQL generated by Gemini -> analysis -> plain-language answer.

Pipeline for one user question:
    1. read the database schema (cached),
    2. ask Gemini to write a read-only SQL query for the question,
    3. validate the query (guardrails) and run it in a read-only transaction,
    4. compute simple statistics over the result,
    5. ask Gemini to turn numbers + stats into an answer in Ukrainian.

Runs standalone for debugging, without Streamlit:
    python agent.py "скільки замовлень за минулий місяць?"
"""

from __future__ import annotations

import os
import re
import sys
import time
from dataclasses import dataclass, field
from decimal import Decimal
from functools import lru_cache

import pandas as pd
import psycopg
from dotenv import load_dotenv
from google import genai
from google.genai import types

load_dotenv()

DEFAULT_MODEL = "gemini-3-flash-preview"
STATEMENT_TIMEOUT = "10s"
GEMINI_ATTEMPTS = 4       # retries for transient 429/503 from the Gemini API
GEMINI_BACKOFF = 2.0      # seconds, doubled after each failed attempt
ROW_LIMIT = 500          # auto-applied when the generated query has no LIMIT
SAMPLE_ROWS_FOR_LLM = 30  # how many result rows the explainer model actually sees

# Only these may open a generated query.
_ALLOWED_PREFIXES = ("select", "with")

# Statements that modify data, schema or permissions. These are the keywords that can
# actually appear inside a single SELECT/WITH statement — notably a data-modifying CTE
# such as `WITH x AS (DELETE FROM t RETURNING *) SELECT * FROM x`, which starts with WITH
# and would otherwise pass the prefix check. Words that cannot open a statement here
# (DO, CALL, VACUUM, ...) are deliberately left out: they would false-positive on ordinary
# table and column names, and the read-only transaction already blocks them.
_FORBIDDEN = re.compile(
    r"\b(insert|update|delete|drop|alter|truncate|create|grant|revoke|merge)\b",
    re.IGNORECASE,
)


class AgentError(Exception):
    """Raised when the agent cannot answer and wants to show a readable reason."""


class CannotAnswerWithSQL(AgentError):
    """The question is not answerable by a query — e.g. it asks about the schema itself.

    `ask` catches this and answers from the schema description instead of failing.
    """


@dataclass
class AgentAnswer:
    """Everything the UI needs to render one turn of the conversation."""

    question: str
    answer: str
    sql: str | None = None
    dataframe: pd.DataFrame | None = None
    stats: dict = field(default_factory=dict)
    error: str | None = None


# --------------------------------------------------------------------------- #
# Configuration
# --------------------------------------------------------------------------- #


def missing_config() -> list[str]:
    """Return the names of required environment variables that are not set.

    The dashboard calls this on startup so it can show a friendly message
    instead of crashing with a traceback.
    """
    return [name for name in ("DATABASE_URL", "GEMINI_API_KEY") if not os.getenv(name)]


def model_name() -> str:
    return os.getenv("GEMINI_MODEL") or DEFAULT_MODEL


@lru_cache(maxsize=1)
def _client() -> genai.Client:
    api_key = os.getenv("GEMINI_API_KEY")
    if not api_key:
        raise AgentError("GEMINI_API_KEY is not set — see .env.example.")
    return genai.Client(api_key=api_key)


def _retry_delay_seconds(exc: Exception) -> float | None:
    """Seconds Gemini asks us to wait, from the RetryInfo in a 429 payload."""
    match = re.search(r"'retryDelay':\s*'(\d+(?:\.\d+)?)s'", str(exc))
    return float(match.group(1)) if match else None


def _quota_exhausted(exc: Exception) -> bool:
    """True for a spent daily quota, as opposed to a brief per-minute rate limit.

    These differ only in the payload: a per-day quota carries a `...PerDay...`
    quotaId and a retryDelay measured in hours. Retrying it just burns requests
    and makes the user wait, so it must fail immediately with a clear message.
    """
    text = str(exc)
    if "PerDay" in text:
        return True
    delay = _retry_delay_seconds(exc)
    return "RESOURCE_EXHAUSTED" in text and delay is not None and delay > 300


def _quota_message(exc: Exception) -> str:
    delay = _retry_delay_seconds(exc)
    when = f" Квота оновиться приблизно через {delay / 3600:.1f} год." if delay else ""
    return (
        f"Вичерпано денну квоту безкоштовного тарифу Gemini для моделі «{model_name()}» "
        f"(20 запитів на добу на модель).{when} "
        "Можна вказати іншу модель у GEMINI_MODEL у файлі .env — у кожної моделі "
        "власна квота — або підключити платний тариф. Дашборд працює без Gemini."
    )


def _is_transient(exc: Exception) -> bool:
    """True for Gemini errors worth retrying: overload and short rate limits.

    Daily-quota exhaustion is deliberately excluded — see `_quota_exhausted`.
    """
    if _quota_exhausted(exc):
        return False
    status = getattr(exc, "code", None) or getattr(exc, "status_code", None)
    if status in (429, 500, 502, 503, 504):
        return True
    return any(
        marker in str(exc)
        for marker in ("UNAVAILABLE", "RESOURCE_EXHAUSTED", "429", "503", "overloaded")
    )


def _ask_gemini(prompt: str, system_instruction: str, temperature: float = 0.0) -> str:
    """Call Gemini, retrying while the API reports a temporary overload.

    `503 UNAVAILABLE` ("high demand") and `429` are routine on the free tier and
    usually clear within seconds, so a few backed-off retries save the whole turn.
    """
    delay = GEMINI_BACKOFF
    last: Exception | None = None

    for attempt in range(1, GEMINI_ATTEMPTS + 1):
        try:
            response = _client().models.generate_content(
                model=model_name(),
                contents=prompt,
                config=types.GenerateContentConfig(
                    system_instruction=system_instruction,
                    temperature=temperature,
                ),
            )
        except Exception as exc:  # noqa: BLE001 - re-raised below unless transient
            if _quota_exhausted(exc):
                raise AgentError(_quota_message(exc)) from exc
            if not _is_transient(exc):
                raise
            if attempt == GEMINI_ATTEMPTS:
                raise AgentError(
                    f"Модель «{model_name()}» перевантажена і не відповіла після "
                    f"{GEMINI_ATTEMPTS} спроб. Спробуй ще раз за хвилину або вкажи "
                    "іншу модель у GEMINI_MODEL у файлі .env."
                ) from exc
            last = exc
            time.sleep(delay)
            delay *= 2
            continue

        text = (response.text or "").strip()
        if text:
            return text
        last = AgentError("empty response")

    raise AgentError(
        "Gemini не відповів після кількох спроб — сервіс перевантажений. "
        f"Спробуй ще раз за хвилину. ({last})"
    )


# --------------------------------------------------------------------------- #
# Database access
# --------------------------------------------------------------------------- #


def get_connection() -> psycopg.Connection:
    """Open a connection to PostgreSQL using DATABASE_URL."""
    dsn = os.getenv("DATABASE_URL")
    if not dsn:
        raise AgentError("DATABASE_URL is not set — see .env.example.")
    try:
        return psycopg.connect(dsn, connect_timeout=10)
    except psycopg.Error as exc:
        raise AgentError(f"Не вдалося підключитися до бази даних: {exc}") from exc


_SCHEMA_SQL = """
SELECT c.table_schema,
       c.table_name,
       c.column_name,
       c.data_type
FROM information_schema.columns AS c
JOIN information_schema.tables AS t
  ON t.table_schema = c.table_schema
 AND t.table_name = c.table_name
WHERE c.table_schema NOT IN ('pg_catalog', 'information_schema')
  AND t.table_type IN ('BASE TABLE', 'VIEW')
ORDER BY c.table_schema, c.table_name, c.ordinal_position
"""

_ROWCOUNT_SQL = """
SELECT n.nspname AS table_schema,
       c.relname AS table_name,
       GREATEST(c.reltuples, 0)::bigint AS approx_rows
FROM pg_class AS c
JOIN pg_namespace AS n ON n.oid = c.relnamespace
WHERE c.relkind IN ('r', 'p')
  AND n.nspname NOT IN ('pg_catalog', 'information_schema')
"""


@lru_cache(maxsize=1)
def load_schema() -> str:
    """Introspect the database and return a compact text description of it.

    The result is embedded in the SQL-generation prompt, so it is kept terse:
    one line per table, with column names, types and an approximate row count.
    """
    with get_connection() as conn:
        conn.read_only = True
        with conn.cursor() as cur:
            cur.execute(_SCHEMA_SQL)
            columns = cur.fetchall()
            cur.execute(_ROWCOUNT_SQL)
            counts = {(schema, table): rows for schema, table, rows in cur.fetchall()}

    if not columns:
        raise AgentError("У базі даних не знайдено жодної таблиці.")

    tables: dict[tuple[str, str], list[str]] = {}
    for schema, table, column, data_type in columns:
        tables.setdefault((schema, table), []).append(f"{column} {data_type}")

    lines = []
    for (schema, table), cols in tables.items():
        approx = counts.get((schema, table))
        suffix = f"  -- ~{approx:,} rows" if approx else ""
        lines.append(f"{schema}.{table}({', '.join(cols)}){suffix}")
    return "\n".join(lines)


def _coerce_decimals(df: pd.DataFrame) -> pd.DataFrame:
    """Convert PostgreSQL NUMERIC columns from Decimal to float.

    psycopg maps NUMERIC to `decimal.Decimal`, which pandas stores in an object
    column. Such a column is invisible to `DataFrame.select_dtypes("number")` —
    so `analyze` would skip it — and Streamlit cannot chart it. Most aggregates
    (avg, sum, round) come back as NUMERIC, so this covers the common case.

    A column is converted only when every non-null value is a Decimal, to avoid
    damaging mixed or text columns.
    """
    for column in df.columns[df.dtypes == object]:
        values = df[column].dropna()
        if not values.empty and values.map(lambda value: isinstance(value, Decimal)).all():
            df[column] = df[column].astype(float)
    return df


def run_query(sql: str) -> pd.DataFrame:
    """Execute an already-validated query in a read-only transaction."""
    with get_connection() as conn:
        conn.read_only = True  # psycopg issues BEGIN READ ONLY
        with conn.cursor() as cur:
            cur.execute(f"SET LOCAL statement_timeout = '{STATEMENT_TIMEOUT}'")
            cur.execute(sql)  # type: ignore[arg-type]
            if cur.description is None:
                raise AgentError("Запит не повернув таблицю результатів.")
            columns = [desc.name for desc in cur.description]
            rows = cur.fetchall()
    return _coerce_decimals(pd.DataFrame(rows, columns=columns))


# --------------------------------------------------------------------------- #
# Guardrails
# --------------------------------------------------------------------------- #


def _strip_sql_comments(sql: str) -> str:
    """Remove -- and /* */ comments so they cannot hide forbidden keywords."""
    sql = re.sub(r"--[^\n]*", " ", sql)
    sql = re.sub(r"/\*.*?\*/", " ", sql, flags=re.DOTALL)
    return sql


def validate_sql(sql: str) -> str:
    """Return a safe version of `sql`, or raise AgentError explaining the refusal.

    The database connection is read-only as well; this is the first of two layers.
    """
    sql = sql.strip()
    if sql.startswith("```"):
        # Strip a markdown fence the model may have added anyway.
        sql = re.sub(r"^```[a-zA-Z]*\s*", "", sql)
        sql = re.sub(r"\s*```$", "", sql).strip()
    sql = sql.rstrip(";").strip()

    if not sql:
        raise AgentError("Модель не згенерувала SQL-запит.")

    bare = _strip_sql_comments(sql)

    if ";" in bare:
        raise AgentError("Дозволено лише один SQL-запит — знайдено кілька команд.")

    if not bare.lstrip().lower().startswith(_ALLOWED_PREFIXES):
        raise AgentError("Дозволені лише запити на читання (SELECT / WITH).")

    forbidden = _FORBIDDEN.search(bare)
    if forbidden:
        raise AgentError(
            f"Запит відхилено: він містить заборонену операцію «{forbidden.group(0).upper()}». "
            "Агент працює лише в режимі читання."
        )

    if not re.search(r"\blimit\s+\d+", bare, re.IGNORECASE):
        sql = f"{sql}\nLIMIT {ROW_LIMIT}"

    return sql


# --------------------------------------------------------------------------- #
# Gemini steps
# --------------------------------------------------------------------------- #

# Domain knowledge that cannot be read from information_schema. It is appended to
# the schema in the SQL-generation prompt: without it the model writes
# `enrolled_at::date`, which fails on ~4% of the rows, and silently treats
# refunded payments as revenue.
SCHEMA_NOTES = """Important notes about this database (an online-course platform):

Dates stored as TEXT — cast them explicitly, never with ::date:
- enrollments.enrolled_at has TWO formats. Parse with:
  CASE WHEN enrolled_at ~ '^\\d{4}-\\d{2}-\\d{2}$' THEN to_date(enrolled_at, 'YYYY-MM-DD')
       WHEN enrolled_at ~ '^\\d{2}\\.\\d{2}\\.\\d{4}$' THEN to_date(enrolled_at, 'DD.MM.YYYY') END
- enrollments.completed_at is always 'YYYY-MM-DD' and is NULL unless the course was finished.
- reviews.review_date looks like 'Feb 14, 2023' -> to_date(review_date, 'Mon DD, YYYY').
- users.signup_date, payments.paid_at and weekly_activity.active_date are real DATE columns.

Business rules:
- enrollments.funnel_state is a ladder: registered -> viewed -> explored -> certified.
  is_certified is 1 only for 'certified'. Certification rate = sum(is_certified) / count(*).
- payments.is_refunded is 1 for a refunded payment. Net revenue must exclude those:
  sum(amount_usd) FILTER (WHERE is_refunded = 0). Plans: monthly ($49), annual ($399).
- users.plan also has 'free' and 'financial_aid', which never appear in payments.
- progress_pct is 0-100.

Joins:
- enrollments.course_id = dim_course.course_id
- enrollments.user_id = users.user_id
- weekly_activity.enrollment_id = enrollments.enrollment_id
- reviews.course_url = dim_course.course_url (reviews are NOT reliably linked to
  enrollments; review_link covers under 1% of reviews)

The data ends on 2023-02-26, so CURRENT_DATE is far outside it. For "last month" or
"recent" questions, anchor on the data instead, e.g. (SELECT max(paid_at) FROM payments).
"""

_SQL_SYSTEM_PROMPT = """You are a PostgreSQL expert. You translate a question into ONE read-only SQL query.

Rules:
- Return ONLY the SQL query. No explanation, no markdown fences, no trailing semicolon.
- Use only SELECT or WITH. Never INSERT, UPDATE, DELETE, DROP, ALTER, CREATE or any other
  statement that changes data, schema or permissions.
- Use only tables and columns that appear in the provided schema. Qualify them with the schema name.
- Prefer aggregates over dumping raw rows; add ORDER BY for "top"/"best"/"worst" questions.
- When ranking by a RATE or share (conversion, certification, refund rate), always also
  select the denominator (count(*)) so the result can be judged, and exclude tiny groups
  with `HAVING count(*) >= 100`. A 50% rate from 2 rows is noise, not a finding.
- Express rates as percentages rounded to one decimal, e.g.
  round(100.0 * sum(is_certified) / count(*), 1), not as a raw 0-1 fraction.
- Always include a LIMIT unless the query returns a single aggregated row.
- If the question cannot be answered from this schema, return exactly: CANNOT_ANSWER
"""

_EXPLAIN_SYSTEM_PROMPT = """Ти — аналітик даних. Ти пояснюєш результат SQL-запиту простою мовою.

Правила:
- Відповідай ВИКЛЮЧНО українською мовою.
- Спирайся лише на надані дані. Ніколи не вигадуй і не округлюй цифри «на око».
- Почни з прямої відповіді на запитання одним реченням, далі — 1–3 речення деталей
  (помітні закономірності, найбільші/найменші значення, динаміка).
- Називай конкретні числа з результату. Великі числа форматуй розділювачами розрядів.
- Якщо у результаті є і частка, і кількість — завжди називай обсяг вибірки поряд із часткою
  («50%, але лише з 36 записів»). Не подавай відсоток з малої вибірки як надійний висновок.
- Якщо результат порожній — скажи про це прямо і припусти чому.
- Без markdown-заголовків, без коду, без переліку SQL. Просто короткий зрозумілий текст.
"""


_SCHEMA_ANSWER_SYSTEM_PROMPT = """Ти — аналітик даних. Користувач питає не про самі дані,
а про будову бази: які є таблиці, що в них лежить, як вони пов'язані.

Правила:
- Відповідай ВИКЛЮЧНО українською мовою.
- Спирайся лише на надану схему та примітки. Не вигадуй таблиць, колонок чи зв'язків.
- Відповідай стисло і структуровано: таблиця — за що відповідає — з чим з'єднується.
- Якщо запитання взагалі не стосується цієї бази даних, чесно скажи про це одним реченням.
- Без SQL, без markdown-заголовків.
"""


def answer_from_schema(question: str, schema: str) -> str:
    """Answer a question about the database structure, without running a query."""
    prompt = (
        f"Схема бази даних:\n{schema}\n\n{SCHEMA_NOTES}\n"
        f"Запитання користувача: {question}"
    )
    return _ask_gemini(prompt, _SCHEMA_ANSWER_SYSTEM_PROMPT, temperature=0.2)


def generate_sql(question: str, schema: str, previous_error: str | None = None) -> str:
    """Ask Gemini for a SQL query answering `question` against `schema`."""
    prompt = f"Database schema:\n{schema}\n\n{SCHEMA_NOTES}\nQuestion: {question}"
    if previous_error:
        prompt += (
            f"\n\nYour previous query failed with this PostgreSQL error:\n{previous_error}\n"
            "Return a corrected query."
        )

    sql = _ask_gemini(prompt, _SQL_SYSTEM_PROMPT)
    if "CANNOT_ANSWER" in sql.upper():
        raise CannotAnswerWithSQL("No SQL query answers this question.")
    return sql


def analyze(df: pd.DataFrame) -> dict:
    """Compute simple descriptive statistics over the query result."""
    stats: dict = {"rows": len(df), "columns": list(df.columns)}
    if df.empty:
        return stats

    numeric = df.select_dtypes(include="number")
    if not numeric.empty:
        stats["numeric"] = {
            column: {
                "sum": float(numeric[column].sum()),
                "mean": float(numeric[column].mean()),
                "min": float(numeric[column].min()),
                "max": float(numeric[column].max()),
            }
            for column in numeric.columns
        }
    return stats


def _format_stats(stats: dict) -> str:
    if "numeric" not in stats:
        return ""
    lines = []
    for column, values in stats["numeric"].items():
        lines.append(
            f"- {column}: sum={values['sum']:,.2f}, mean={values['mean']:,.2f}, "
            f"min={values['min']:,.2f}, max={values['max']:,.2f}"
        )
    return "Statistics over the numeric columns:\n" + "\n".join(lines)


def explain(question: str, sql: str, df: pd.DataFrame, stats: dict) -> str:
    """Turn the query result into a plain-language answer in Ukrainian."""
    preview = df.head(SAMPLE_ROWS_FOR_LLM)
    truncated = (
        f"\n(показано перші {SAMPLE_ROWS_FOR_LLM} з {len(df)} рядків)"
        if len(df) > SAMPLE_ROWS_FOR_LLM
        else ""
    )
    prompt = "\n\n".join(
        part
        for part in [
            f"Запитання користувача: {question}",
            f"Виконаний SQL-запит:\n{sql}",
            f"Результат ({len(df)} рядків):\n{preview.to_string(index=False)}{truncated}",
            _format_stats(stats),
        ]
        if part
    )
    return _ask_gemini(prompt, _EXPLAIN_SYSTEM_PROMPT, temperature=0.2)


# --------------------------------------------------------------------------- #
# Orchestration
# --------------------------------------------------------------------------- #


def ask(question: str) -> AgentAnswer:
    """Answer one user question end to end. Never raises — errors land in `AgentAnswer.error`."""
    question = question.strip()
    if not question:
        return AgentAnswer(question=question, answer="", error="Порожнє запитання.")

    sql: str | None = None
    try:
        schema = load_schema()

        try:
            sql = validate_sql(generate_sql(question, schema))
        except CannotAnswerWithSQL:
            # A question about the database itself, not about its contents.
            return AgentAnswer(question=question, answer=answer_from_schema(question, schema))

        try:
            df = run_query(sql)
        except psycopg.Error as exc:
            # One self-repair attempt: show the model the database error.
            sql = validate_sql(generate_sql(question, schema, previous_error=str(exc)))
            df = run_query(sql)

        stats = analyze(df)
        return AgentAnswer(
            question=question,
            answer=explain(question, sql, df, stats),
            sql=sql,
            dataframe=df,
            stats=stats,
        )
    except AgentError as exc:
        return AgentAnswer(question=question, answer="", sql=sql, error=str(exc))
    except psycopg.Error as exc:
        return AgentAnswer(
            question=question,
            answer="",
            sql=sql,
            error=f"Помилка виконання SQL-запиту: {exc}",
        )
    except Exception as exc:  # noqa: BLE001 - the UI should show a message, not a traceback
        return AgentAnswer(
            question=question,
            answer="",
            sql=sql,
            error=f"Неочікувана помилка: {type(exc).__name__}: {exc}",
        )


def main() -> int:
    if len(sys.argv) < 2:
        print(f'Usage: python {os.path.basename(__file__)} "your question"')
        return 2

    result = ask(" ".join(sys.argv[1:]))

    if result.sql:
        print("--- SQL ---")
        print(result.sql)
    if result.dataframe is not None:
        print(f"\n--- RESULT ({len(result.dataframe)} rows) ---")
        print(result.dataframe.head(20).to_string(index=False))
    if result.error:
        print(f"\n--- ERROR ---\n{result.error}")
        return 1

    print("\n--- ANSWER ---")
    print(result.answer)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
